use Illuminate\Support\Facades\Route;

Route::middleware('guest')->group(function () {
    Route::get('/login', [AuthController::class, 'create'])->name('login');
    Route::post('/login', [AuthController::class, 'store'])->middleware('throttle:6,1')->name('login.store');
    Route::get('/forgot-password', [AuthController::class, 'forgotForm'])->name('password.request');
    Route::post('/forgot-password', [AuthController::class, 'sendResetLink'])->middleware('throttle:6,1')->name('password.email');
    Route::get('/reset-password/{token}', [AuthController::class, 'resetForm'])->name('password.reset');
    Route::post('/reset-password', [AuthController::class, 'resetPassword'])->middleware('throttle:6,1')->name('password.update');
});

Route::middleware(['auth', 'role:admin,staff', 'activity'])->group(function () {
    Route::get('/', fn () => redirect()->route('dashboard'));
    Route::get('/dashboard', DashboardController::class)->name('dashboard');
    Route::get('/profile', [ProfileController::class, 'edit'])->name('profile.edit');
    Route::put('/profile', [ProfileController::class, 'update'])->name('profile.update');
    Route::put('/profile/password', [ProfileController::class, 'updatePassword'])->name('profile.password');
    Route::post('/logout', [AuthController::class, 'destroy'])->name('logout');
    Route::get('/notifications', [NotificationController::class, 'index'])->name('notifications.index');
    Route::post('/notifications/read-all', [NotificationController::class, 'readAll'])->name('notifications.read-all');
    Route::post('/notifications/{notification}/read', [NotificationController::class, 'read'])->name('notifications.read');
    Route::get('/events', [EventController::class, 'index'])->name('events.index');
    Route::get('/events/create', [EventController::class, 'create'])->middleware('role:admin,staff')->name('events.create');
    Route::post('/event-categories', [EventController::class, 'storeCategory'])->middleware('role:admin,staff')->name('event-categories.store');
    Route::post('/events', [EventController::class, 'store'])->middleware('role:admin,staff')->name('events.store');
    Route::get('/events/{event}', [EventController::class, 'show'])->name('events.show');
    Route::get('/events/{event}/edit', [EventController::class, 'edit'])->middleware('role:admin,staff')->name('events.edit');
    Route::match(['put', 'patch'], '/events/{event}', [EventController::class, 'update'])->middleware('role:admin,staff')->name('events.update');
    Route::delete('/events/{event}', [EventController::class, 'destroy'])->middleware('role:admin,staff')->name('events.destroy');
    Route::post('/events/{event}/schedule', [EventScheduleController::class, 'store'])->middleware('role:admin,staff')->name('events.schedule.store');
    Route::patch('/event-schedules/{schedule}', [EventScheduleController::class, 'update'])->middleware('role:admin,staff')->name('event-schedules.update');
    Route::delete('/event-schedules/{schedule}', [EventScheduleController::class, 'destroy'])->middleware('role:admin,staff')->name('event-schedules.destroy');
    Route::get('/venues', [VenueController::class, 'index'])->middleware('role:admin,staff')->name('venues.index');
    Route::post('/venues', [VenueController::class, 'storeVenue'])->middleware('role:admin,staff')->name('venues.store');
    Route::patch('/venues/{venue}/availability', [VenueController::class, 'availability'])->middleware('role:admin,staff')->name('venues.availability');
    Route::post('/venue-bookings', [VenueController::class, 'storeBooking'])->middleware('role:admin,staff')->name('venue-bookings.store');
    Route::patch('/venue-bookings/{booking}', [VenueController::class, 'review'])->middleware('role:admin,staff')->name('venue-bookings.review');
    Route::get('/students', [StudentController::class, 'index'])->middleware('role:admin,staff')->name('students.index');
    Route::post('/students', [StudentController::class, 'store'])->middleware('role:admin,staff')->name('students.store');
    Route::post('/departments', [StudentController::class, 'storeDepartment'])->middleware('role:admin,staff')->name('departments.store');
    Route::get('/registrations', [RegistrationController::class, 'index'])->middleware('role:admin,staff')->name('registrations.index');
    Route::get('/participants/names', [RegistrationController::class, 'nameList'])->middleware('role:admin,staff')->name('participants.namelist');
    Route::get('/participants/names.csv', [RegistrationController::class, 'exportNameList'])->middleware('role:admin,staff')->name('participants.namelist.export');
    Route::get('/teams', [TeamController::class, 'index'])->middleware('role:admin,staff')->name('teams.index');
    Route::post('/teams', [TeamController::class, 'store'])->middleware('role:admin,staff')->name('teams.store');
    Route::post('/registrations', [RegistrationController::class, 'store'])->middleware('role:admin,staff')->name('registrations.store');
    Route::patch('/registrations/{registration}', [RegistrationController::class, 'review'])->middleware('role:admin,staff')->name('registrations.review');
    Route::patch('/registrations/{registration}/attendance', [RegistrationController::class, 'attendance'])->middleware('role:admin,staff')->name('registrations.attendance');
    Route::get('/judging', [JudgingController::class, 'index'])->middleware('role:admin,staff')->name('judging.index');
    Route::post('/judging/criteria', [JudgingController::class, 'criterion'])->middleware('role:admin,staff')->name('judging.criteria');
    Route::post('/judging/assignments', [JudgingController::class, 'assignJudge'])->middleware('role:admin,staff')->name('judging.assign');
    Route::post('/judging/scores', [JudgingController::class, 'score'])->middleware('role:admin,staff')->name('judging.scores');
    Route::post('/judging/{event}/calculate', [JudgingController::class, 'calculate'])->middleware('role:admin,staff')->name('judging.calculate');
    Route::post('/judging/{event}/finalize', [JudgingController::class, 'finalize'])->middleware('role:admin,staff')->name('judging.finalize');
    Route::get('/users', [UserController::class, 'index'])->middleware('role:admin')->name('users.index');
    Route::post('/users', [UserController::class, 'store'])->middleware('role:admin')->name('users.store');
    Route::patch('/users/{user}', [UserController::class, 'update'])->middleware('role:admin')->name('users.update');
    Route::get('/activity', [ActivityController::class, 'index'])->middleware('role:admin')->name('activity.index');
    Route::get('/awards', [AwardController::class, 'index'])->middleware('role:admin,staff')->name('awards.index');
    Route::get('/awards/generate', fn () => redirect()->route('awards.index'))->middleware('role:admin,staff')->name('awards.generate.page');
    Route::post('/awards/generate', [AwardController::class, 'generate'])->middleware('role:admin,staff')->name('awards.generate');
    Route::patch('/awards/{award}/distribution', [AwardController::class, 'distribute'])->middleware('role:admin,staff')->name('awards.distribute');
    Route::get('/refreshments', [RefreshmentController::class, 'index'])->middleware('role:admin,staff')->name('refreshments.index');
    Route::post('/refreshments', [RefreshmentController::class, 'store'])->middleware('role:admin,staff')->name('refreshments.store');
    Route::post('/refreshments/distributions', [RefreshmentController::class, 'distribute'])->middleware('role:admin,staff')->name('refreshments.distribute');
    Route::get('/leave-requests', [LeaveController::class, 'index'])->middleware('role:admin,staff')->name('leave.index');
    Route::get('/leave-request-template', [LeaveController::class, 'template'])->middleware('role:admin,staff')->name('leave.template');
    Route::post('/leave-requests', [LeaveController::class, 'store'])->middleware('role:admin,staff')->name('leave.store');
    Route::patch('/leave-requests/{leaveRequest}', [LeaveController::class, 'review'])->middleware('role:admin,staff')->name('leave.review');
    Route::get('/leave-requests/{leaveRequest}/document', [LeaveController::class, 'download'])->middleware('role:admin,staff')->name('leave.document');
    Route::get('/seminars', [SeminarController::class, 'index'])->middleware('role:admin,staff')->name('seminars.index');
    Route::post('/lecturers', [SeminarController::class, 'storeLecturer'])->middleware('role:admin,staff')->name('lecturers.store');
    Route::post('/seminars', [SeminarController::class, 'storeSeminar'])->middleware('role:admin,staff')->name('seminars.store');
    Route::post('/seminar-sessions', [SeminarController::class, 'storeSession'])->middleware('role:admin,staff')->name('seminar-sessions.store');
    Route::get('/mis', [IntegrationController::class, 'index'])->middleware('role:admin,staff')->name('mis.index');
    Route::post('/mis/students/import', [IntegrationController::class, 'importStudents'])->middleware('role:admin,staff')->name('mis.students.import');
    Route::get('/mis/events/{event}/results.csv', [IntegrationController::class, 'exportResults'])->middleware('role:admin,staff')->name('mis.results.export');
    Route::get('/reports', [ReportController::class, 'index'])->middleware('role:admin,staff')->name('reports.index');
    Route::get('/reports/{type}.csv', [ReportController::class, 'download'])->middleware('role:admin,staff')->name('reports.download');
